-- Generated by automation/assemble-people-migration.py. Stage 6.
-- Source: database/functions/people/access_fanout.sql
-- One access-change fanout for organizer role edits and removal. No new commit.
CREATE OR REPLACE FUNCTION public.publish_unit_user_access_change_internal_v1(p_commit_id uuid,p_unit bigint,p_user uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_occasion bigint; v_revision bigint;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.client_commits WHERE commit_id=p_commit_id AND unit=p_unit) THEN
  RAISE foreign_key_violation USING MESSAGE='organizer access fanout requires its commit'; END IF;
  FOR v_occasion IN SELECT ou.occasion FROM public.occasion_users ou
    JOIN public.occasions o ON o.id=ou.occasion
    WHERE o.unit=p_unit AND ou."user"=p_user ORDER BY ou.occasion LOOP
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('occasion_user','occasion',v_occasion,p_user::text,1)
    ON CONFLICT (aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE SET
      version=public.client_aggregate_versions.version+1,
      updated_at=clock_timestamp();
    INSERT INTO public.client_sync_private_scopes
      (component,occasion,user_id,source_revision)
    VALUES ('private_profile',v_occasion,p_user,1)
    ON CONFLICT (component,occasion,user_id) DO UPDATE SET
      source_revision=public.client_sync_private_scopes.source_revision+1,
      updated_at=now() RETURNING source_revision INTO v_revision;
    INSERT INTO public.client_commit_components
      (commit_id,component,scope_type,scope_id,user_id,resulting_revision)
    VALUES (p_commit_id,'private_profile','occasion',v_occasion,
      p_user,v_revision);
  END LOOP;
END $$;
REVOKE ALL ON FUNCTION public.publish_unit_user_access_change_internal_v1(uuid,bigint,uuid) FROM PUBLIC,anon,authenticated,service_role;


-- Source: database/functions/people/scope.sql
-- Lock the stored resource scope and live authorization facts before delegating.
-- Row locks also fence revocation while a bounded read is in flight.
CREATE OR REPLACE FUNCTION public.lock_people_scope_internal_v1(p_occasion bigint,p_organization bigint DEFAULT NULL,p_unit bigint DEFAULT NULL)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE resource public.occasions%ROWTYPE; organizer public.units%ROWTYPE;
BEGIN
 IF auth.uid() IS NULL THEN RAISE insufficient_privilege USING MESSAGE='authenticated identity required'; END IF;
 IF p_occasion IS NOT NULL THEN
  SELECT * INTO resource FROM public.occasions WHERE id=p_occasion FOR SHARE;
  IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='occasion unavailable'; END IF;
  IF (p_organization IS NOT NULL AND resource.organization IS DISTINCT FROM p_organization)
    OR (p_unit IS NOT NULL AND resource.unit IS DISTINCT FROM p_unit) THEN
   RAISE insufficient_privilege USING MESSAGE='occasion scope changed'; END IF;
  SELECT * INTO organizer FROM public.units WHERE id=resource.unit FOR SHARE;
 ELSE
  SELECT * INTO organizer FROM public.units WHERE id=p_unit FOR SHARE;
 END IF;
 IF organizer.id IS NULL OR (p_organization IS NOT NULL AND organizer.organization IS DISTINCT FROM p_organization) THEN
  RAISE insufficient_privilege USING MESSAGE='organizer scope changed'; END IF;
 PERFORM 1 FROM public.organization_users WHERE organization=organizer.organization AND "user"=auth.uid() FOR SHARE;
 PERFORM 1 FROM public.unit_users WHERE unit=organizer.id AND "user"=auth.uid() FOR SHARE;
 IF p_occasion IS NOT NULL THEN
  PERFORM 1 FROM public.occasion_users WHERE occasion=p_occasion AND "user"=auth.uid() FOR SHARE;
 END IF;
END $$;
REVOKE ALL ON FUNCTION public.lock_people_scope_internal_v1(bigint,bigint,bigint) FROM PUBLIC,anon,authenticated,service_role;


-- Source: database/functions/people/profile_changes.sql
-- Named changes share the profile receipt/version owner. No new profile writer.
CREATE OR REPLACE FUNCTION public.prepare_profile_change_internal_v1(p_current jsonb,p_intent jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE changes jsonb; spec jsonb:= $contract${"profile":{"name":{"type":"string","maxLength":512,"nullable":true},"surname":{"type":"string","maxLength":512,"nullable":true},"phone":{"type":"string","maxLength":512,"nullable":true},"diet":{"type":"string","maxLength":512,"nullable":true},"text1":{"type":"string","maxLength":512,"nullable":true},"text2":{"type":"string","maxLength":512,"nullable":true},"text3":{"type":"string","maxLength":512,"nullable":true},"sex":{"type":"string","maxLength":32,"nullable":true},"note":{"type":"string","maxLength":8192,"nullable":true},"birthDate":{"type":"string","pattern":"^([0-9]{4}-[0-9]{2}-[0-9]{2})?$","nullable":true}},"roles":{"is_editor":{"type":"boolean"},"is_editor_view":{"type":"boolean"},"is_editor_order":{"type":"boolean"},"is_editor_order_view":{"type":"boolean"},"is_cleaning_crew":{"type":"boolean"},"is_cleaning_blocked":{"type":"boolean"},"is_receptionist":{"type":"boolean"},"is_approver":{"type":"boolean"},"is_approved":{"type":"boolean"},"is_manager":{"type":"boolean"},"is_volunteer":{"type":"boolean"},"role":{"type":"integer","minimum":0,"maximum":2147483647,"nullable":true}}}$contract$::jsonb; kind text;
BEGIN
 IF NOT (p_intent ?| ARRAY['profileChange','roleChange']) THEN RETURN p_intent; END IF;
 IF p_intent ? 'profileChange' AND p_intent ? 'roleChange'
  OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_intent) k WHERE k NOT IN ('occasion','user','profileChange','roleChange')) THEN
  RAISE invalid_parameter_value USING MESSAGE='one explicit profile or role intent required'; END IF;
 kind:=CASE WHEN p_intent ? 'roleChange' THEN 'roles' ELSE 'profile' END;
 changes:=coalesce(p_intent->'profileChange',p_intent->'roleChange');
 IF jsonb_typeof(changes) IS DISTINCT FROM 'object' THEN RAISE invalid_parameter_value USING MESSAGE='named profile changes required'; END IF;
 PERFORM public.validate_configuration_value_internal_v1(changes,jsonb_build_object('type','object','properties',spec->kind));
 IF kind='profile' THEN
  RETURN jsonb_build_object('occasion',p_intent->'occasion','user',p_intent->'user',
   'data',coalesce(nullif(p_current->'data','null'::jsonb),'{}')||changes);
 END IF;
 RETURN jsonb_build_object('occasion',p_intent->'occasion','user',p_intent->'user',
   'data',coalesce(nullif(p_current->'data','null'::jsonb),'{}')||CASE WHEN changes ? 'is_volunteer' THEN jsonb_build_object('is_volunteer',changes->'is_volunteer') ELSE '{}'::jsonb END)
   ||(changes-'is_volunteer');
END $$;
REVOKE ALL ON FUNCTION public.prepare_profile_change_internal_v1(jsonb,jsonb) FROM PUBLIC,anon,authenticated,service_role;


-- Source: database/functions/units/begin_unit_client_mutation_v1.sql
CREATE OR REPLACE FUNCTION public.begin_unit_client_mutation_v1(p_command_id uuid, p_command_name text, p_unit bigint, p_actor_id uuid, p_request_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE v_receipt public.client_mutation_receipts%ROWTYPE; v_inserted integer;
BEGIN
  IF p_actor_id IS NULL OR p_actor_id IS DISTINCT FROM auth.uid()
     OR p_command_id IS NULL OR p_unit IS NULL
     OR p_command_name !~ '^[a-z][a-z0-9_.]{2,95}$'
     OR p_request_sha256 !~ '^[0-9a-f]{64}$'
     OR NOT (CASE WHEN p_command_name IN ('occasion.create','occasion.setup.finalize')
       THEN public.can_create_occasion(p_unit)
       WHEN p_command_name='occasion.delete' THEN public.can_delete_occasion_in_unit(p_unit)
       WHEN p_command_name IN ('unit.information.save','unit.information.delete')
         THEN public.can_write_unit_information(p_unit)
       WHEN p_command_name IN ('unit.icon.save','unit.icon.delete')
         THEN public.can_write_unit_icons(p_unit)
       WHEN p_command_name IN ('unit.email_template.save','unit.email_template.reset','unit.email_banner.save')
         THEN public.can_write_unit_email_templates(p_unit)
       WHEN p_command_name IN ('profile.unit_access.delete','profile.unit_user.save') THEN public.can_manage_unit_users(p_unit)
       WHEN p_command_name='unit.config.save' THEN public.can_manage_unit_configuration(p_unit)
       WHEN p_command_name='occasion.duplicate' THEN public.can_copy_occasion_target(p_unit)
       ELSE false END) THEN
    RAISE insufficient_privilege USING MESSAGE='invalid unit mutation receipt claim';
  END IF;
  INSERT INTO public.client_mutation_receipts
    (command_id,command_name,unit,actor_id,request_sha256)
  VALUES (p_command_id,p_command_name,p_unit,p_actor_id,p_request_sha256)
  ON CONFLICT (command_id) DO NOTHING;
  GET DIAGNOSTICS v_inserted=ROW_COUNT;
  SELECT * INTO STRICT v_receipt FROM public.client_mutation_receipts
    WHERE command_id=p_command_id FOR UPDATE;
  IF v_receipt.command_name IS DISTINCT FROM p_command_name
     OR v_receipt.occasion IS NOT NULL OR v_receipt.unit IS DISTINCT FROM p_unit
     OR v_receipt.actor_id IS DISTINCT FROM p_actor_id OR v_receipt.actor_client_id IS NOT NULL
     OR v_receipt.request_sha256 IS DISTINCT FROM p_request_sha256 THEN
    RAISE invalid_parameter_value USING MESSAGE='command id was already used with different request data';
  END IF;
  IF v_receipt.status='completed' THEN
    RETURN jsonb_build_object('disposition','replay','response',v_receipt.response);
  ELSIF v_receipt.status='expired' THEN
    RETURN jsonb_build_object('disposition','replay',
      'response',public.expired_client_mutation_response_v1(v_receipt));
  END IF;
  IF v_inserted<>1 THEN RAISE serialization_failure
    USING MESSAGE='incomplete mutation receipt cannot be resumed'; END IF;
  RETURN jsonb_build_object('disposition','claimed');
END; $function$
;
REVOKE ALL ON FUNCTION public.begin_unit_client_mutation_v1(p_command_id uuid, p_command_name text, p_unit bigint, p_actor_id uuid, p_request_sha256 text) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.begin_unit_client_mutation_v1(uuid,text,bigint,uuid,text) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.begin_unit_client_mutation_v1(uuid,text,bigint,uuid,text) TO service_role;


-- Source: database/functions/users/update_unit_user.sql
CREATE OR REPLACE FUNCTION public.update_unit_user_internal_v1(
    input_data jsonb
) RETURNS jsonb
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    -- Variables extracted from input_data
    v_user uuid;
    v_unit bigint;
    v_is_manager boolean;
    v_is_editor boolean;
    v_is_editor_view boolean;
    v_data jsonb;

    -- Internal helper variables
    v_update_user_payload jsonb;
    v_update_user_result jsonb;
    v_final_user_uuid uuid;
BEGIN
    -- 1. Extract and validate fields from the input JSONB
    v_user := (input_data->>'user')::uuid;
    v_unit := (input_data->>'unit')::bigint;
    v_is_manager := (input_data->>'is_manager')::boolean;
    v_is_editor := (input_data->>'is_editor')::boolean;
    v_is_editor_view := (input_data->>'is_editor_view')::boolean;

    -- Default the 'data' field to an empty jsonb object if it's null or an empty string
    v_data := CASE
                WHEN input_data->>'data' IS NULL OR input_data->>'data' = ''
                THEN '{}'::jsonb
                ELSE input_data->'data'
              END;

    -- 2. Perform initial validation
    IF v_unit IS NULL THEN
        RETURN jsonb_build_object('code', 400, 'message', 'The "unit" field is required.');
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.units WHERE id = v_unit) THEN
      RETURN jsonb_build_object('code', 404, 'message', 'Unit not found');
    END IF;

    -- 3. Authorization Check: Verify the calling user is a manager for the specified unit
    IF NOT public.can_manage_unit_users(v_unit) THEN
      RETURN jsonb_build_object('code', 403, 'message', 'Unauthorized: You must be a manager of this unit.');
    END IF;

    -- 4. Prepare payload to call the update_user function
    -- The `update_user` function expects email, name, surname etc., to be inside its 'data' payload.
    -- We will ensure these fields are present in v_data before making the call.
    IF input_data ? 'name' THEN v_data := v_data || jsonb_build_object('name', input_data->>'name'); END IF;
    IF input_data ? 'surname' THEN v_data := v_data || jsonb_build_object('surname', input_data->>'surname'); END IF;
    IF input_data ? 'sex' THEN v_data := v_data || jsonb_build_object('sex', input_data->>'sex'); END IF;
    IF v_user IS NULL AND input_data ? 'email' THEN
        v_data := v_data || jsonb_build_object('email', input_data->>'email');
    END IF;

    v_update_user_payload := jsonb_build_object(
        'user', v_user,
        'unit', v_unit,
        'data', v_data
    );

    -- 5. Call update_user and handle its response
    v_update_user_result := public.update_user_internal_v1(v_update_user_payload);

    -- If the sub-function did not return a success code (200 or 201), pass its error response through.
    IF (v_update_user_result->>'code')::int NOT IN (200, 201) THEN
        RETURN v_update_user_result;
    END IF;

    -- Extract the definitive user UUID returned from the update_user function
    v_final_user_uuid := (v_update_user_result->>'user')::uuid;

    -- Sanity check in case update_user succeeds but doesn't return a UUID
    IF v_final_user_uuid IS NULL THEN
      RETURN jsonb_build_object('code', 500, 'message', 'Failed to retrieve user UUID after profile update.', 'lol', (v_update_user_result));
    END IF;

    -- 6. Insert or Update the user's roles in the unit (UPSERT)
    INSERT INTO public.unit_users("user", unit, is_manager, is_editor, is_editor_view, data)
    VALUES (v_final_user_uuid, v_unit, v_is_manager, v_is_editor, v_is_editor_view, v_data)
    ON CONFLICT ("user", unit) DO UPDATE
    SET is_manager     = EXCLUDED.is_manager,
        is_editor      = EXCLUDED.is_editor,
        is_editor_view = EXCLUDED.is_editor_view,
        data           = EXCLUDED.data;

    -- 7. Return a final success response
    RETURN jsonb_build_object(
      'code', 200,
      'message', 'User role in unit updated successfully',
      'user', v_final_user_uuid::text
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
      'code', 500,
      'message', SQLERRM
    );
END;
$$ LANGUAGE plpgsql;
REVOKE ALL ON FUNCTION public.update_unit_user_internal_v1(jsonb) FROM PUBLIC,anon,authenticated,service_role;


-- Source: database/functions/people/unit_user_command.sql
-- Receipt boundary around the existing organizer-user persistence owner.
CREATE OR REPLACE FUNCTION public.save_unit_user_client_sync_v1(p_unit bigint,p_user uuid,p_command_id uuid,p_expected_version bigint,p_changes jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE initial jsonb; current_user_row jsonb; after_row jsonb; result jsonb; usr uuid:=p_user; ver bigint;
 c public.client_commits%ROWTYPE; intent jsonb; mode text;
BEGIN
 PERFORM public.lock_people_scope_internal_v1(NULL,NULL,p_unit);
 IF NOT public.can_manage_unit_users(p_unit) THEN RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
 IF jsonb_typeof(p_changes) IS DISTINCT FROM 'object' OR octet_length(p_changes::text)>131072 THEN RAISE invalid_parameter_value USING MESSAGE='invalid organizer user'; END IF;
 mode:=p_changes->>'kind';
 IF mode='roles' THEN
  IF usr IS NULL OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_changes) k WHERE k NOT IN ('kind','is_manager','is_editor','is_editor_view'))
    OR EXISTS(SELECT 1 FROM jsonb_each(p_changes-'kind') x WHERE jsonb_typeof(x.value)<>'boolean') THEN
   RAISE invalid_parameter_value USING MESSAGE='explicit organizer roles required'; END IF;
 ELSIF mode='profile' THEN
  PERFORM public.prepare_profile_change_internal_v1('{}',jsonb_build_object('profileChange',p_changes-'kind'));
 ELSIF mode IS DISTINCT FROM 'editor' THEN RAISE invalid_parameter_value USING MESSAGE='unknown organizer user intent';
 END IF;
 initial:=public.begin_unit_client_mutation_v1(p_command_id,'profile.unit_user.save',p_unit,auth.uid(),
  encode(extensions.digest(convert_to(jsonb_build_object('unit',p_unit,'user',p_user,'version',p_expected_version,'changes',p_changes)::text,'UTF8'),'sha256'),'hex'));
 IF initial->>'disposition'='replay' THEN RETURN initial->'response'; END IF;
 -- Serialize creation, update and revocation for this organizer. Existing UI
 -- callers also enter this owner through the released update_unit_user facade.
 PERFORM pg_catalog.pg_advisory_xact_lock(-p_unit);
 IF NOT public.can_manage_unit_users(p_unit) THEN RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
 IF usr IS NOT NULL THEN
  PERFORM 1 FROM public.user_info WHERE id=usr FOR UPDATE;
  SELECT to_jsonb(uu) INTO current_user_row FROM public.unit_users uu WHERE uu.unit=p_unit AND uu."user"=usr FOR UPDATE;
  IF current_user_row IS NULL THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',404,'{}'); END IF;
  INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
   VALUES('unit_user','unit',p_unit,usr::text,0) ON CONFLICT DO NOTHING;
  SELECT version INTO ver FROM public.client_aggregate_versions WHERE aggregate_type='unit_user' AND scope_type='unit' AND scope_id=p_unit AND aggregate_id=usr::text FOR UPDATE;
  IF p_expected_version IS DISTINCT FROM ver THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('version',ver)); END IF;
 ELSE
  IF EXISTS(SELECT 1 FROM public.unit_users uu JOIN public.user_info ui ON ui.id=uu."user" WHERE uu.unit=p_unit AND lower(btrim(ui.email_readonly))=lower(btrim(p_changes#>>'{data,email}'))) THEN
   RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,'{}'); END IF;
  IF mode<>'editor' THEN RAISE invalid_parameter_value USING MESSAGE='creation uses organizer editor'; END IF;
 END IF;
 IF mode='editor' THEN
  intent:=(p_changes-'kind')||jsonb_build_object('unit',p_unit,'user',usr);
  -- Omitted metadata must survive ordinary grid saves.
  intent:=jsonb_set(intent,'{data}',coalesce(nullif(current_user_row->'data','null'::jsonb),'{}')||coalesce(nullif(intent->'data','null'::jsonb),'{}'));
 ELSE
  intent:=coalesce(current_user_row,'{}')||jsonb_build_object('unit',p_unit,'user',usr);
  IF mode='roles' THEN intent:=intent||(p_changes-'kind');
  ELSE intent:=intent||jsonb_build_object('data',coalesce(nullif(current_user_row->'data','null'::jsonb),'{}')||(p_changes-'kind'));
  END IF;
 END IF;
 result:=public.update_unit_user_internal_v1(intent);
 IF coalesce((result->>'code')::int,500) NOT IN(200,201) THEN
  -- The legacy persistence function catches exceptions in its own subtransaction.
  RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',coalesce((result->>'code')::int,400),'{}'); END IF;
 usr:=(result->>'user')::uuid;
 SELECT to_jsonb(uu) INTO after_row FROM public.unit_users uu WHERE uu.unit=p_unit AND uu."user"=usr;
 INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES('unit_user','unit',p_unit,usr::text,1) ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id)
  DO UPDATE SET version=client_aggregate_versions.version+1,updated_at=clock_timestamp() RETURNING version INTO ver;
 INSERT INTO public.client_commits(unit,actor_id,actor_display,actor_kind,source,change_class)
 SELECT p_unit,auth.uid(),nullif(concat_ws(' ',ui.name,ui.surname),''),'user','profile.unit_user.save','profile' FROM public.user_info ui WHERE ui.id=auth.uid() RETURNING * INTO c;
 INSERT INTO public.client_commit_items(commit_id,item_index,entity_type,entity_id,operation,safe_label,changed_fields)
 VALUES(c.commit_id,0,'unit_user',usr::text,CASE WHEN p_user IS NULL THEN 'insert' ELSE 'update' END,'Organizer membership',ARRAY[mode]);
 IF current_user_row->'is_manager' IS DISTINCT FROM after_row->'is_manager'
  OR current_user_row->'is_editor' IS DISTINCT FROM after_row->'is_editor'
  OR current_user_row->'is_editor_view' IS DISTINCT FROM after_row->'is_editor_view' THEN
  PERFORM public.publish_unit_user_access_change_internal_v1(c.commit_id,p_unit,usr);
 END IF;
 PERFORM public.fanout_unit_catalog_v1(c.commit_id,p_unit);
 RETURN public.finish_client_mutation_v1(p_command_id,jsonb_build_object('status','applied','code',200,'data',jsonb_build_object('userId',usr,'version',ver),
  'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,'commitId',c.commit_id,'replayed',false,'occurredAt',c.occurred_at),
  'sync',jsonb_build_object('replacements','[]'::jsonb)),c.commit_id);
END $$;
REVOKE ALL ON FUNCTION public.save_unit_user_client_sync_v1(bigint,uuid,uuid,bigint,jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.save_unit_user_client_sync_v1(bigint,uuid,uuid,bigint,jsonb) TO authenticated,service_role;

-- Released clients use the same owner; only they may obtain an implicit baseline.
CREATE OR REPLACE FUNCTION public.update_unit_user(input_data jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE uid uuid:=(input_data->>'user')::uuid; unit_id bigint:=(input_data->>'unit')::bigint; ver bigint; result jsonb;
BEGIN
 PERFORM public.lock_people_scope_internal_v1(NULL,NULL,unit_id);
 IF NOT public.can_manage_unit_users(unit_id) THEN RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(-unit_id);
 SELECT coalesce(v.version,0) INTO ver FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
 ON v.aggregate_type='unit_user' AND v.scope_type='unit' AND v.scope_id=unit_id AND v.aggregate_id=uid::text;
 result:=public.save_unit_user_client_sync_v1(unit_id,uid,extensions.gen_random_uuid(),ver,(input_data-'unit'-'user')||'{"kind":"editor"}');
 RETURN jsonb_build_object('code',result->'code','user',result#>'{data,userId}');
END $$;
REVOKE ALL ON FUNCTION public.update_unit_user(jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.update_unit_user(jsonb) TO authenticated,service_role;


-- Source: database/functions/users/unit_access_deletion.sql
-- Canonical owner recovered from the recorded effective main schema.
-- Public signatures, response envelopes and existing execution roles are preserved.

CREATE OR REPLACE FUNCTION public.delete_unit_user_internal_v1(usr uuid, unit_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
    IF NOT public.can_manage_unit_users(unit_id) THEN
      RAISE insufficient_privilege USING MESSAGE='unit manager required';
    END IF;
    DELETE FROM unit_users
    WHERE "user" = usr AND unit = unit_id;

    UPDATE occasion_users
    SET is_editor = false,
        is_manager = false,
        is_editor_view = false
    WHERE "user" = usr
      AND occasion IN (SELECT id FROM occasions WHERE unit = unit_id);

    RETURN jsonb_build_object('code', 200);
END;
$function$
;
REVOKE ALL ON FUNCTION public.delete_unit_user_internal_v1(uuid,bigint) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION public.delete_unit_user_internal_v1(uuid,bigint) TO postgres;

CREATE OR REPLACE FUNCTION public.delete_unit_user_client_sync_v1(p_user uuid, p_unit bigint, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_before jsonb;
  v_after jsonb; v_result jsonb; v_commit public.client_commits%ROWTYPE;

BEGIN
  IF v_actor IS NULL OR p_user IS NULL
    OR NOT public.can_manage_unit_users(p_unit) THEN
    RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
  PERFORM public.lock_people_scope_internal_v1(NULL,NULL,p_unit);
  PERFORM pg_catalog.pg_advisory_xact_lock(-p_unit);
  IF NOT public.can_manage_unit_users(p_unit) THEN RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'unit',p_unit,'userId',p_user)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_unit_client_mutation_v1(p_command_id,
    'profile.unit_access.delete',p_unit,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT jsonb_build_object('unitUser',(SELECT to_jsonb(uu)
      FROM public.unit_users uu WHERE uu.unit=p_unit AND uu."user"=p_user),
    'occasionUsers',COALESCE((SELECT jsonb_agg(to_jsonb(ou) ORDER BY ou.occasion)
      FROM public.occasion_users ou JOIN public.occasions o ON o.id=ou.occasion
      WHERE o.unit=p_unit AND ou."user"=p_user),'[]'::jsonb)) INTO v_before;
  v_result:=public.delete_unit_user_internal_v1(p_user,p_unit);
  SELECT jsonb_build_object('unitUser',(SELECT to_jsonb(uu)
      FROM public.unit_users uu WHERE uu.unit=p_unit AND uu."user"=p_user),
    'occasionUsers',COALESCE((SELECT jsonb_agg(to_jsonb(ou) ORDER BY ou.occasion)
      FROM public.occasion_users ou JOIN public.occasions o ON o.id=ou.occasion
      WHERE o.unit=p_unit AND ou."user"=p_user),'[]'::jsonb)) INTO v_after;
  IF v_before IS NOT DISTINCT FROM v_after THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('userId',p_user)); END IF;
  INSERT INTO public.client_commits
    (unit,actor_id,actor_display,actor_kind,source,change_class)
  SELECT p_unit,v_actor,nullif(concat_ws(' ',ui.name,ui.surname),''),'user',
    'profile.unit_access.delete','profile' FROM public.user_info ui
    WHERE ui.id=v_actor RETURNING * INTO v_commit;
  INSERT INTO public.client_commit_items
    (commit_id,item_index,entity_type,entity_id,operation,safe_label,changed_fields)
  VALUES (v_commit.commit_id,0,'unit_user',p_user::text,'delete','Unit access',
    ARRAY['rights']);
  PERFORM public.publish_unit_user_access_change_internal_v1(v_commit.commit_id,p_unit,p_user);
  RETURN public.finish_client_mutation_v1(p_command_id,jsonb_build_object(
    'status','applied','code',200,'data',jsonb_build_object('userId',p_user),
    'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
      'commitId',v_commit.commit_id,'replayed',false,'occurredAt',v_commit.occurred_at),
    'sync',jsonb_build_object('replacements','[]'::jsonb)),v_commit.commit_id);
END; $function$
;
REVOKE ALL ON FUNCTION public.delete_unit_user_client_sync_v1(uuid,bigint,uuid) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION public.delete_unit_user_client_sync_v1(uuid,bigint,uuid) TO postgres,authenticated,service_role;

